{
  "name": "Aged, Blind, and Disabled (ABD) Medicaid",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "summary": "Arizona uses SSI-related financial methodology for ABD Medicaid; one source indicates Arizona applies income/resource rules more restrictive than SSI for people age 65+, blind, or disabled[1]. Publicly available secondary sources consistently describe an ABD income limit around 100% of the Federal Poverty Level for non-long-term-care ABD coverage, with one source giving 2026 estimates of about $1,304/month for one person and noting annual updates[2][7][13].",
      "table": [
        {
          "household_size": "1",
          "monthly_income_limit": "$1,304 (approximate 2026 figure)[7][13]"
        },
        {
          "household_size": "2",
          "monthly_income_limit": "$1,764 (approximate 2026 figure implied by FPL-based ABD estimates; verify with AHCCCS at application time)[7]"
        }
      ],
      "notes": [
        "Arizona ABD Medicaid is not presented as a broad household-size program like MAGI Medicaid; eligibility is based on the applicant’s own aged/blind/disabled category and SSI-related financial rules[1][8].",
        "SSI recipients are generally treated as automatically eligible for the Medicaid category and still must file a separate Medicaid application in Arizona under this state plan approach[1]."
      ]
    },
    "asset_limits": {
      "summary": "Arizona ABD Medicaid is unusual because most seniors and people with disabilities in the non-long-term-care category have no asset/resource limit, according to a secondary state summary[10][14]. However, state-plan documents show Arizona uses SSI resource methodology for aged/blind/disabled Medicaid and a separate application process[1].",
      "what_counts": [
        "If resource testing applies in a specific subprogram or long-term-care pathway, countable resources typically include cash, bank accounts, investments, and some non-exempt real and personal property[1][9]."
      ],
      "what_is_exempt": [
        "Primary residence is typically exempt in Medicaid resource rules while the applicant lives there or intends to return, subject to program rules[1].",
        "One vehicle is commonly excluded in SSI-style Medicaid methodology, along with certain burial arrangements and personal effects[1]."
      ],
      "important_caveat": "Because Arizona’s ABD rules are often summarized as having no asset limit for non-LTC ABD, families should not assume a $2,000 SSI-style cap unless they are applying for a different Medicaid pathway such as long-term care[10][13]."
    },
    "other_requirements": [
      "Must be an Arizona resident[3].",
      "Must be a U.S. citizen or eligible non-citizen[3].",
      "Must be age 65+, blind, or disabled[1][8].",
      "For disability-based eligibility, the disability must meet SSA/SSI-style standards used by AHCCCS[1][15].",
      "Separate Medicaid application is required even for SSI beneficiaries[1]."
    ]
  },
  "benefits": {
    "type": "service",
    "value": "ABD Medicaid covers medical services for elderly, blind, and disabled members; secondary Arizona sources say it can pay for physician visits, hospital care, prescription drugs, and ancillary services, and may cover some benefits not paid by Original Medicare[5][7][13]. A state-specific example cited by secondary sources says Arizona ABD covers up to $1,000 per year in preventive, diagnostic, and therapeutic dental services plus another $1,000 for emergency dental care[5].",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: Health-e-Arizona Plus at https://www.healthearizonaplus.gov[2][13]",
      "Phone help: 1-855-432-7587 (1-855-HEA-PLUS)[2][13]",
      "Mail: Application for Benefits sent to AHCCCS Medical Assistance Specialty Programs (MA-SP), 801 E Jefferson St, Phoenix, AZ 85034[2]",
      "In person: local eligibility offices / in-person submission options are referenced by secondary Arizona guidance[2]"
    ],
    "processing_time": "Not clearly stated in the sources gathered; if approved through standard AHCCCS processing, timing can vary by case complexity and whether disability verification is needed[1][2].",
    "waitlist": null,
    "forms": [
      "Application for AHCCCS Health Insurance and Medicare Savings Programs (DE-103 / DE103)[3][6]",
      "Application for Benefits (for mail-in submission referenced by Arizona guidance)[2]"
    ],
    "documents": [
      "Proof of Arizona residency[3]",
      "Proof of U.S. citizenship or eligible immigration status[3]",
      "Social Security number(s)[3]",
      "Proof of income such as Social Security award letters, pension statements, or recent pay stubs[7]",
      "Medical/disability evidence if disability status is not already established through SSA/SSI[1][15]",
      "Identification and any Medicare information if the applicant has Medicare[5][6]"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Arizona program administered by AHCCCS; not county-restricted in the sources gathered[1][2].",
    "regional_variations": "The core ABD Medicaid eligibility rules are statewide. The practical experience can differ by local office, managed care plan, and provider network, but no formal region-specific eligibility variation was identified in the gathered sources[1][2].",
    "offices_or_providers": [
      "AHCCCS / Arizona Health Care Cost Containment System",
      "AHCCCS Medical Assistance Specialty Programs (MA-SP), 801 E Jefferson St, Phoenix, AZ 85034[2]"
    ]
  },
  "official_source": "https://www.azahcccs.gov/",
  "gotchas": [
    "Arizona requires a separate Medicaid application for aged, blind, and disabled coverage even when SSA handles SSI eligibility[1].",
    "ABD Medicaid in Arizona is often confused with ALTCS; ALTCS is the long-term-care pathway and has very different rules, including a nursing-facility-level-of-care test and stricter asset rules[9].",
    "Families often miss that Medicare and ABD Medicaid can work together, with ABD sometimes helping pay Medicare cost sharing and filling coverage gaps[5].",
    "Income limits and program details can change yearly, so current AHCCCS figures should be checked before submitting an application[2][13].",
    "Do not assume every disabled older adult has an asset limit; secondary Arizona summaries indicate no asset limit for many non-LTC ABD applicants[10][14]."
  ],
  "data_shape_notes": "This program is age/disability-category based, not a standard household-MAGI program; Arizona also uses separate application handling for aged/blind/disabled cases and may have no asset test for non-long-term-care ABD applicants, which is the main data-shape difference families miss[1][10][14]."
}
